  // Initialize ray tracing data structures
  ray = new Ray()
  intersection = null

  // Shoot a ray from the camera through the pixel
  ray.origin = cameraPosition
  ray.direction = (pixel coordinates - cameraPosition) / (pixel width * pixel height)

  // Intersection loop: traverse the scene and find intersections
  while intersection is null :
    // Check for intersections with primitives (e.g., triangles, spheres)
    intersection = intersectWithPrimitives(ray)

    // If no intersection, fallback to texture sampling (bilinear filtering)
    if intersection is null :
