                Currency = "usd",
                PaymentMethodTypes = new[] { "card" }
            };

            return await paymentIntentService.CreateAsync(paymentIntentOptions);
        }

        private async Task ChargeCustomer(string paymentIntentId, int trialAmount)
        {
