            var paymentIntent = await paymentIntentService.GetAsync(paymentIntentId);

            // Charge the customer for the trial amount
            var codeVerificationOptions = new PaymentIntentConfirmOptions
            {
                PaymentMethodOptions = new PaymentMethodOptions
                {
                    Card = new PaymentMethodOptionsCard
                    {
                        PaymentMethodTypes = new[] { "card" }
                    }
                }
            };

            await paymentIntentService.ConfirmAsync(paymentIntentId, codeVerificationOptions);
        }

